#include <Arduino.h>

void lights(bool red, bool yellow, bool green) {
  digitalWrite(8, red ? HIGH : LOW);
  digitalWrite(9, yellow ? HIGH : LOW);
  digitalWrite(10, green ? HIGH : LOW);
}

void setup() {
  pinMode(2, INPUT);
  pinMode(8, OUTPUT);
  pinMode(9, OUTPUT);
  pinMode(10, OUTPUT);
  lights(false, false, true);
}

void loop() {
  if (digitalRead(2) == HIGH) {
    lights(false, true, false);
    delay(1000);
    lights(true, false, false);
    delay(2000);
    lights(false, false, true);
  } else {
    lights(false, false, true);
  }
}
